update pages set contenu = '{"sections":[{"type":"heros","h1":"Maintenance tuyauterie industrielle","mecanisme":"Nous remettons vos circuits dans le plan de maintenance : inspection datée, mesure d''épaisseur, reprise des supports, puis remplacement de tronçon, éprouvé en pression avant remise en service.","cta":"Demander une intervention","telephone":"04 78 33 72 05","phraseDelai":"Rappel dans l''heure, du lundi au vendredi de 8h00 à 18h30. L''astreinte 24/24 et 7/7 prend le relais la nuit et le week-end."},{"type":"chiffres","chiffres":[{"valeur":"10 %","libelle":"des candidats retenus, après entretien technique ET comportemental"},{"valeur":"4","libelle":"agences, plus des hubs techniques, pour partir du bassin le plus proche"},{"valeur":"+ 120","libelle":"clients, dont plus de 80 réguliers"},{"valeur":"24/24 et 7/7","libelle":"astreinte, pour les sites couverts"}]},{"type":"probleme","punchline":"Une ligne vapeur qui perce, et c''est tout un atelier consigné un lundi matin.","puces":[{"accroche":"Vos canalisations ne figurent dans aucun plan de maintenance.","texte":"Elles sont pourtant l''artère de l''usine, et le premier signal est une flaque au sol."},{"accroche":"La corrosion sous calorifuge ne se voit pas.","texte":"En pied de support, aux points de rétention d''eau, elle travaille des années sans témoin."},{"accroche":"La vanne n''a pas été manœuvrée depuis des années.","texte":"Elle bloque le jour de la consignation, quand vous en avez le plus besoin."},{"accroche":"Le support est rompu, la ligne entière travaille.","texte":"Les brides fuient, la soudure fatigue, et chacun traite le symptôme du mois."}]},{"type":"offre","lignes":[{"prestation":{"accroche":"Les fuites arrêtées avant l''arrêt de production","texte":"reprise d''étanchéité sur bride, manchette, piquage, vanne ou soudure fissurée."},"benefice":"La consignation d''urgence un lundi matin devient une reprise programmée."},{"prestation":{"accroche":"Les tronçons remplacés proprement","texte":"dépose, préfabrication, soudure, repose, essai en pression."},"benefice":"Un remplacement préparé se déroule dans la fenêtre prévue, pas au-delà."},{"prestation":{"accroche":"L''inspection datée de chaque ligne","texte":"mesure d''épaisseur par ultrasons, état des supports, corrosion sous calorifuge, points singuliers."},"benefice":"Les reprises se planifient à froid, avec des chiffres à l''appui du budget."},{"prestation":{"accroche":"Les supports et guidages repris","texte":"cause racine de beaucoup de désordres répétés."},"benefice":"La fatigue s''arrête, les brides cessent de fuir les unes après les autres."},{"prestation":{"accroche":"Les modifications et piquages","texte":"dérivation ajoutée, ligne déplacée, adaptation à une nouvelle machine."},"benefice":"Votre implantation suit la production sans chantier de reconstruction."},{"prestation":{"texte":"**Le serrage au couple et le remplacement de la boulonnerie et des joints.**"},"benefice":"Le suintement à la bride se règle en une visite au lieu d''un cycle de resserrages."},{"prestation":{"accroche":"Les fluides et matériaux courants couverts","texte":"acier noir pour la vapeur et l''eau surchauffée, inox pour l''agroalimentaire et la chimie, cuivre et matériaux de synthèse pour les utilités."},"benefice":"Le type de tube est choisi pour le fluide, pas pour ce qui reste en stock."},{"prestation":{"accroche":"Un compte rendu à chaque passage","texte":"constat, travaux réalisés, matériaux utilisés, mesures relevées, points à surveiller."},"benefice":"Il alimente votre GMAO et sert de preuve écrite le jour d''un audit."}],"prose":[{"texte":"La soudure décide de la tenue de l''ensemble : nos travaux de [soudure industrielle](/expertises/soudure/) suivent les mêmes exigences de préparation et de contrôle. Une rupture en cours se traite par le [dépannage industriel](/offres/depannage-industriel/)."}]},{"type":"deroule","etapes":[{"titre":"Vous décrivez la situation","texte":"fluide transporté, pression de service, température, matériau en place, adresse du site. Quatre champs, ou un appel au 04 78 33 72 05."},{"titre":"Un technicien vous rappelle dans l''heure.","texte":"Ces informations décident de tout le reste : une ligne vapeur, un réseau d''air comprimé et une conduite d''eau glacée n''appellent pas la même approche."},{"titre":"Inspection","texte":"examen visuel, mesure d''épaisseur par ultrasons, contrôle des supports et des points bas, relevé des cotes réelles."},{"titre":"Préparation","texte":"consignation, vidange, purge, plan de prévention, permis de feu, protection des équipements voisins. Le risque se traite avant, pas pendant."},{"titre":"Réalisation","texte":"découpe, préfabrication du tronçon, soudure, repose, remplacement de la boulonnerie et des joints."},{"titre":"Épreuve et remise en service","texte":"essai en pression, contrôle d''étanchéité, redémarrage accompagné avec votre équipe, puis compte rendu écrit."}]},{"type":"garanties","puces":[{"accroche":"Le rappel dans l''heure, du lundi au vendredi de 8h00 à 18h30.","texte":"L''astreinte 24/24 et 7/7 couvre la nuit et le week-end sur les sites concernés."},{"accroche":"Aucune remise en service sans épreuve.","texte":"Essai en pression, contrôle d''étanchéité, épaisseurs et reprises consignées par écrit. Une certification ISO 9001 côté client impose cette traçabilité : nos comptes rendus sont faits pour ça."},{"accroche":"Un technicien évalué en entretien technique et comportemental","texte":", 10 % des candidats retenus, dont les habilitations et autorisations prévues par votre plan de prévention sont vérifiées avant l''intervention. Le tuyauteur travaille avec le soudeur et le mécanicien quand le chantier l''exige."}]},{"type":"cta","question":"Besoin de savoir quelles lignes tiendront encore douze mois, et lesquelles non ?","bouton":"Demander une intervention","rappel":"Ou appelez le 04 78 33 72 05, du lundi au vendredi de 8h00 à 18h30. Rappel dans l''heure."},{"type":"preuves","preuves":[{"titre":"Remise en état d''un site de traitement des eaux industrielles, risque chimique","texte":"un technicien habilité RC1 mobilisé 6 mois, habilitations obtenues avant la première intervention","lienLibelle":"Étude de cas SUEZ : remise en état d''un site","lienHref":"/preuves/suez-remise-en-etat/"},{"titre":"Construction d''un site industriel de recherche et développement, matériaux bas carbone","texte":"pilotage de chantier et coordination, soudure et chaudronnerie parmi les domaines mobilisés selon les besoins","lienLibelle":"Étude de cas ORTHUS x ECOCEM : nouveau site","lienHref":"/preuves/orthus-ecocem/"},{"titre":"Montage de portiques de lavage partout en France","texte":"levage et raccordements compris, mécanique, électricité et automatisme réunis sur le même chantier","lienLibelle":"Étude de cas ORTHUS x WASHTEC : installation de stations","lienHref":"/preuves/orthus-washtec/"},{"titre":"Montages et déplacements de machines, étanchéité et isolation","texte":"lignes et sous-ensembles assemblés, profils réunis selon le chantier, sur 2025","lienLibelle":"Étude de cas SOPREMA : travaux ponctuels","lienHref":"/preuves/soprema/"},{"titre":"Contrat de maintenance sur un site agroalimentaire de grande échelle, Belgique","texte":"renfort en place depuis octobre 2024, premier contrat Migen hors de France","lienLibelle":"Étude de cas McCAIN : Belgique","lienHref":"/preuves/mccain-belgique/"}]},{"type":"objections","questions":[{"question":"Combien coûte une reprise de tuyauterie ?","reponse":"Le chiffrage dépend du fluide, de la pression de service, de l''accès et de la longueur reprise. Tout est établi sur devis, déplacements annoncés dans le devis et jamais découverts sur la facture."},{"question":"Faut-il arrêter la production pour une réparation ?","reponse":"Souvent oui, le temps de consigner et de vidanger le tronçon. L''inspection, elle, se fait en fonctionnement : examen visuel, mesure d''épaisseur, contrôle des supports. C''est ce qui permet de planifier les reprises pendant un arrêt programmé."},{"question":"Reprenez-vous une installation posée par une autre entreprise ?","reponse":"Oui. Nous commençons par un état des lieux, sans jugement sur l''existant, puis nous proposons les corrections essentielles, classées par risque. Aucun catalogue à écouler, donc aucun chantier inutile proposé."},{"question":"Qui répond de la sécurité sur un circuit sous pression ?","reponse":"Nos techniciens, dans votre cadre. Analyse avant chantier, consignation, purge, protection incendie, balisage. Une erreur de consignation est un accident : les consignes de sécurité passent avant la cadence."},{"question":"Assurez-vous la mise en conformité d''une installation ancienne ?","reponse":"Nous réalisons l''audit, nous identifions les écarts aux règles relatives aux équipements sous pression et nous chiffrons la remise en conformité. Une étude préalable est nécessaire pour un chiffrage juste."},{"question":"Couvrez-vous notre région, et les petits sites ?","reponse":"Oui aux deux. 4 agences, Lyon (siège), Montréal, Dubaï et Madrid, et des hubs de techniciens dans les grandes villes de France partout en France. Donnez-nous l''adresse du site, nous vous disons quelle agence intervient."}]},{"type":"ctaFinal","question":"Besoin que vos circuits entrent enfin dans le plan de maintenance ?","bouton":"Demander une intervention"}]}'::jsonb where path = '/expertises/tuyauterie/';
